import{_ as a,C as o,o as s,c as n,aj as i,G as r,j as l}from"./chunks/framework.BwH0p-pt.js";const b=JSON.parse('{"title":"AI Agent Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/ai-agent/analytics.md","filePath":"2.1/ai-agent/analytics.md","lastUpdated":1781079046000}'),d={name:"2.1/ai-agent/analytics.md"};function h(g,e,u,c,p,m){const t=o("ImagePopup");return s(),n("div",null,[e[0]||(e[0]=i('<h1 id="ai-agent-analytics" tabindex="-1">AI Agent Analytics <a class="header-anchor" href="#ai-agent-analytics" aria-label="Permalink to &quot;AI Agent Analytics&quot;">​</a></h1><p>The <strong>AI Agent Analytics</strong> dashboard shows you how the agent is being used and what it&#39;s costing. Because every AI request consumes tokens (and tokens cost money), this dashboard is how you keep the bill predictable, spot unusual usage patterns, and tune the daily budget.</p><h2 id="what-does-the-analytics-dashboard-do" tabindex="-1">What does the Analytics dashboard do? <a class="header-anchor" href="#what-does-the-analytics-dashboard-do" aria-label="Permalink to &quot;What does the Analytics dashboard do?&quot;">​</a></h2><p>It surfaces three things in one place:</p><ol><li><strong>What&#39;s happening right now</strong> — today&#39;s token consumption vs. the daily budget, and how much budget is left.</li><li><strong>What has happened historically</strong> — conversation counts, tool calls, and token spend per day, per user, and per operation type.</li><li><strong>What it has cost</strong> — token usage translated into an estimated dollar figure based on your provider&#39;s pricing.</li></ol><p>Use it to answer questions like <em>&quot;Who is using the agent most heavily this week?&quot;</em>, <em>&quot;Which operation types are the biggest token sinks?&quot;</em>, and <em>&quot;Am I about to hit my daily cap?&quot;</em></p><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>Every time a user sends a message to the AI Agent Chat, UnoPim records:</p><ul><li><strong>Who</strong> sent the message (the admin user).</li><li><strong>Which tools</strong> the agent called to respond.</li><li><strong>How many tokens</strong> were consumed (prompt + completion, for every tool call).</li><li><strong>When</strong> the turn happened.</li></ul><p>The dashboard aggregates these records to produce the counters, charts, and user-level breakdowns. Records persist as long as your session/log retention policy allows, so historical trend analysis is available out-of-the-box.</p><h3 id="where-the-daily-budget-comes-from" tabindex="-1">Where the daily budget comes from <a class="header-anchor" href="#where-the-daily-budget-comes-from" aria-label="Permalink to &quot;Where the daily budget comes from&quot;">​</a></h3><p>The <strong>Daily Token Budget</strong> is a single global number set under <strong>Magic AI → Settings → Agentic PIM → Daily Token Budget</strong> (e.g., <code>500000</code>). Every tool call the agent makes decrements the running total for the day. When the total hits zero, the agent replies with a budget-exhausted notice to any user that tries to send a message. At midnight (server time), the counter resets.</p><p>The dashboard shows <strong>three derived figures</strong> on top of that raw counter: today&#39;s usage, remaining budget, and the utilization percentage.</p><h2 id="analytics-dashboard-overview" tabindex="-1">Analytics Dashboard Overview <a class="header-anchor" href="#analytics-dashboard-overview" aria-label="Permalink to &quot;Analytics Dashboard Overview&quot;">​</a></h2><p>The dashboard gives you a centralized view of all AI Agent activity. From it, you can monitor:</p><ul><li><strong>Total tokens consumed</strong> over a selected time period.</li><li><strong>Number of conversations</strong> initiated by each admin user.</li><li><strong>Number of tool calls</strong> executed by the agent.</li><li><strong>Daily and weekly usage trends</strong> displayed in visual charts.</li></ul><p>The dashboard is accessible from the admin panel and is available to users with the appropriate permissions.</p><h2 id="token-budget-tracking" tabindex="-1">Token Budget Tracking <a class="header-anchor" href="#token-budget-tracking" aria-label="Permalink to &quot;Token Budget Tracking&quot;">​</a></h2><p>The AI Agent operates on a <strong>daily token budget</strong> — a single global cap shared across all admin users. The dashboard displays:</p><ul><li><strong>Daily token usage</strong> — How many tokens have been consumed today across all users.</li><li><strong>Remaining budget</strong> — Tokens still available for the current day.</li><li><strong>Budget utilization percentage</strong> — Visual indicator (e.g., a progress bar) of how much of the daily budget has been used.</li></ul><p>When the daily token budget is exhausted, the AI Agent pauses for the rest of the day. It notifies users that the limit has been reached and resumes normal operation the following day when the budget resets.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep an eye on the daily utilization if your team leans on auto-enrichment or bulk operations. Those tasks consume more tokens per turn than simple lookup queries.</p></div><h2 id="monitoring-ai-usage-and-costs" tabindex="-1">Monitoring AI Usage and Costs <a class="header-anchor" href="#monitoring-ai-usage-and-costs" aria-label="Permalink to &quot;Monitoring AI Usage and Costs&quot;">​</a></h2><p>The dashboard helps you understand the cost implications of the agent. Key metrics include:</p><ul><li><strong>Token consumption per user</strong> — Which team members are using the agent most heavily.</li><li><strong>Token consumption per operation type</strong> — Which types of operations (product creation, auto-enrichment, data quality scans, image generation, etc.) consume the most tokens.</li><li><strong>Cost estimation</strong> — Tokens translated into a dollar estimate based on the pricing of your selected provider/model.</li></ul><p>This information is useful for budgeting, for spotting runaway usage, and for deciding whether to assign a cheaper model to a particular capability (e.g., use a lighter model for translation and keep the premium model for content generation).</p><h2 id="configuring-daily-token-budgets" tabindex="-1">Configuring Daily Token Budgets <a class="header-anchor" href="#configuring-daily-token-budgets" aria-label="Permalink to &quot;Configuring Daily Token Budgets&quot;">​</a></h2><p>To set or adjust the daily token budget:</p><ol><li>Navigate to <strong>Magic AI → Settings</strong> in the admin panel.</li><li>Open the <strong>Agentic PIM</strong> section.</li><li>Set the <strong>Daily Token Budget</strong> field (e.g., <code>500000</code>).</li><li>Click <strong>Save Configuration</strong> to apply.</li></ol><p>The budget applies globally across all admin users. Once combined usage reaches the daily limit, the agent pauses until midnight.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with a conservative daily budget and raise it gradually as you learn your team&#39;s usage patterns. This prevents surprise spikes during rollout.</p></div><h2 id="viewing-usage-history-and-trends" tabindex="-1">Viewing Usage History and Trends <a class="header-anchor" href="#viewing-usage-history-and-trends" aria-label="Permalink to &quot;Viewing Usage History and Trends&quot;">​</a></h2><p>The <strong>Usage History</strong> section lets you review past activity over customizable date ranges. It provides:</p><ul><li><strong>Daily usage breakdown</strong> — Day-by-day view of token consumption and conversation counts.</li><li><strong>Weekly and monthly summaries</strong> — Aggregated views for longer-term trend analysis.</li><li><strong>Peak usage identification</strong> — Highlights days or periods with unusually high usage so you can investigate before they become a problem.</li></ul><p>Use this historical data to inform budget allocation, spot power users, and identify operations that might benefit from a cheaper model.</p><h2 id="how-analytics-ties-to-the-other-agent-controls" tabindex="-1">How analytics ties to the other agent controls <a class="header-anchor" href="#how-analytics-ties-to-the-other-agent-controls" aria-label="Permalink to &quot;How analytics ties to the other agent controls&quot;">​</a></h2><p>The analytics dashboard is the observability layer that sits on top of the controls you configured under <strong>Magic AI → Settings → Agentic PIM</strong>. Together they form a continuous feedback loop:</p>',37)),r(t,{src:"/assets/2.1/images/ai-agent/analytics-feedback-loop.png",alt:"AI Agent Management Feedback Loop"}),e[1]||(e[1]=l("p",null,"A typical rollout is: start with a conservative Daily Token Budget and Manual Review approval, watch the analytics for a week, raise the budget where it's safe, and move trusted workflows to Auto-Approve based on what the dashboard tells you.",-1))])}const k=a(d,[["render",h]]);export{b as __pageData,k as default};
